/* Local presentation switches only; no device, transport, audio or persistence. */
(function(){'use strict';const $=id=>document.getElementById(id);let muted=false,speaker=false,video=false;
function render(){for(const [id,on,label]of [['call-demo-mic',muted,muted?'已静音（模拟）':'静音'],['call-demo-speaker',speaker,speaker?'扬声器开（模拟）':'扬声器']]){$(id).setAttribute('aria-pressed',String(on));$(id+'-label').textContent=label;}document.body.dataset.callMode=video?'video':'voice';$('call-demo-video').setAttribute('aria-pressed',String(video));$('call-demo-video').setAttribute('aria-label',video?'切换到语音布局，始终无音频':'切换到视频占位布局，不使用摄像头');$('call-demo-video-label').textContent=video?'切换语音':'切换视频';$('call-mode-name').textContent=video?'视频通话布局 · 占位':'语音通话布局';}
$('call-demo-mic').addEventListener('click',()=>{muted=!muted;render();});$('call-demo-speaker').addEventListener('click',()=>{speaker=!speaker;render();});$('call-demo-video').addEventListener('click',()=>{video=!video;render();});
function reset(){muted=speaker=video=false;render();}for(const id of ['call-start','call-end'])$(id).addEventListener('click',reset);window.addEventListener('pagehide',reset);document.addEventListener('visibilitychange',()=>{if(document.hidden)reset();});reset();})();
